    // A discrete ship/airframe/missile echo is compact in cross-range or has vertical structure;
    // a moving low target can also stand out through MTI Doppler.  No single feature is mandatory:
    // this preserves stationary ships while rejecting broad, flat sea-resolution cells.
    const crossCompact=Math.exp(-Math.max(0,crossM-24)/72),rangeCompact=Math.exp(-Math.max(0,rangeM-135)/210),verticalStructure=clamp(Math.max(altM/9,verticalM/5.5),0,1),kinematicContrast=smoothstep(clamp((surfaceDoppler-1.2)/8.8,0,1)),dopplerCompact=Math.exp(-Math.max(0,dopplerSpread-2.5)/15);
