    const score=clamp(.28*crossCompact+.12*rangeCompact+.38*verticalStructure+.14*kinematicContrast+.08*dopplerCompact-broadPenalty-flatSurfacePenalty,0,1);
    return {score,crossCompact,rangeCompact,verticalStructure,kinematicContrast,dopplerCompact,broadPenalty,flatSurfacePenalty,estimatedAltitudeM:altM,surfaceRelativeDopplerMps:surfaceDoppler};
  }

